namespace block0 {
template<class T> T* allocate(unsigned n) { return new T[n]; }
template<class T> int (*matrix(unsigned n))[3] { return new int[n][3]; }
template<class T> auto shape(unsigned n) -> decltype(new T[n]) { return new T[n]; }

template<class T> struct Outer {
    struct Inner {
        friend class Outer<T>;
    private:
        int value;
    public:
        Inner(int v): value(v) {}
    };
    int get(const Inner& p) { return p.value; }
};
template<class T> struct Simple {
    struct Inner {
        friend Simple<T>;
    private:
        int value;
    public:
        Inner(int v): value(v) {}
    };
    int get(const Inner& p) { return p.value; }
};

struct Base { typedef int result; enum code { ok = 3 }; };
template<class T> struct Service : Base {
    result get(T) const;
    code status() const;
};
template<class U> typename Service<U>::result Service<U>::get(U) const { return 9; }
template<class U> typename Service<U>::code Service<U>::status() const { return Base::ok; }

static_assert(sizeof(Outer<int>::Inner) == sizeof(int), "layout");
}
